import { useIntl } from 'react-intl';

import {
  NumberSizeableText,
  SizableText,
  XStack,
  YStack,
} from '@onekeyhq/components';
import { useCurrency } from '@onekeyhq/kit/src/components/Currency';
import {
  BaseMarketTokenPrice,
  MarketTokenPrice,
} from '@onekeyhq/kit/src/views/Market/components/MarketTokenPrice';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';
import type { IMarketTokenDetail } from '@onekeyhq/shared/types/marketV2';

import { StockMarketStatusBadge } from '../../../components/PerpsBadges';
import { TokenTagsPopover } from '../../../components/TokenTagsPopover';
import { useBtcMetadataContext } from '../../hooks/BtcMetadataContext';
import { useMarketDetailDisplayData } from '../../hooks/useMarketDetailDisplayData';
import {
  MARKET_CAP_FORMATTER,
  USD_CURRENCY_FORMATTER,
  formatPriceChangeDisplay,
  formatRatioValue,
  formatStatValueWithFormatter,
} from '../../utils/statValue';
import { TokenSecurityAlert } from '../TokenSecurityAlert';
import { useTokenSecurity } from '../TokenSecurityAlert/hooks';

import { InformationPanelSkeleton } from './InformationPanelSkeleton';
import { resolveDisplayedPriceChange } from './stockMobilePriceChange';
import { StockMobilePriceHeader } from './StockMobilePriceHeader';

import type { IMarketMobileDetailKind } from '../../utils/marketMobileDetailKind';

// 4pt top padding plus the 16pt stock badges.
const STOCK_TAG_ROW_MIN_HEIGHT = 20;

function getPriceSizeByValue(price: string) {
  if (price.startsWith('0.0000')) {
    return '$headingLg';
  }
  if (price.startsWith('0.000')) {
    return '$headingXl';
  }
  return '$heading3xl';
}

function StatRow({ label, value }: { label: string; value: string }) {
  return (
    <XStack pointerEvents="none" gap="$1" width="100%" jc="space-between">
      <SizableText size="$bodySm" color="$textSubdued">
        {label}
      </SizableText>
      <SizableText size="$bodySmMedium">{value}</SizableText>
    </XStack>
  );
}

function HeaderStatRows({
  isStockToken,
  isPreview,
  stock,
  btcMetadata,
  fallback,
}: {
  isStockToken: boolean;
  isPreview: boolean;
  stock: IMarketTokenDetail['stock'];
  btcMetadata: ReturnType<typeof useBtcMetadataContext>;
  fallback: {
    marketCap: string;
    liquidity: string;
    holders: string;
  };
}) {
  const intl = useIntl();
  // A stock preview has no stock stats yet; keep the stock labels in place so
  // loading does not swap the rows under the user.
  if (isStockToken && (stock || isPreview)) {
    return (
      <>
        <StatRow
          label={intl.formatMessage({ id: ETranslations.global_market_cap })}
          value={formatStatValueWithFormatter(
            stock?.marketCap,
            USD_CURRENCY_FORMATTER,
          )}
        />
        <StatRow
          label={intl.formatMessage({
            id: ETranslations.dexmarket_stock_24h_volume,
          })}
          value={formatStatValueWithFormatter(
            stock?.assetAnalysis?.volume24h,
            USD_CURRENCY_FORMATTER,
          )}
        />
        <StatRow
          label={intl.formatMessage({
            id: ETranslations.dexmarket_stock_pe_ttm,
          })}
          value={formatRatioValue(stock?.tradingActivity?.peRatio)}
        />
      </>
    );
  }
  if (btcMetadata) {
    return (
      <>
        <StatRow
          label={intl.formatMessage({ id: ETranslations.global_market_cap })}
          value={formatStatValueWithFormatter(
            btcMetadata.marketCap,
            USD_CURRENCY_FORMATTER,
          )}
        />
        <StatRow
          label={intl.formatMessage({
            id: ETranslations.dexmarket_stock_24h_volume,
          })}
          value={formatStatValueWithFormatter(
            btcMetadata.volume24h,
            USD_CURRENCY_FORMATTER,
          )}
        />
        <StatRow
          label={intl.formatMessage({
            id: ETranslations.dexmarket_btc_circulating_supply,
          })}
          value={formatStatValueWithFormatter(
            btcMetadata.circulatingSupply,
            MARKET_CAP_FORMATTER,
          )}
        />
      </>
    );
  }
  return (
    <>
      <StatRow
        label={intl.formatMessage({ id: ETranslations.global_market_cap })}
        value={fallback.marketCap}
      />
      <StatRow
        label={intl.formatMessage({ id: ETranslations.global_liquidity })}
        value={fallback.liquidity}
      />
      <StatRow
        label={intl.formatMessage({ id: ETranslations.dexmarket_holders })}
        value={fallback.holders}
      />
    </>
  );
}

export function InformationPanel({
  mobileDetailKind,
}: {
  mobileDetailKind?: IMarketMobileDetailKind;
}) {
  const intl = useIntl();
  const currencyInfo = useCurrency();
  const { tokenDetail, networkId, isPreviewTokenDetail, isStockToken } =
    useMarketDetailDisplayData();
  const btcMetadata = useBtcMetadataContext();
  const tokenAddress = tokenDetail?.address;

  const { securityData } = useTokenSecurity({
    tokenAddress: tokenAddress ?? '',
    networkId: networkId ?? '',
  });

  // Figma stock chart header: price, dollar change, Share/Token toggle, and
  // the market-status row. Desktop and web keep the previous stat header.
  if (platformEnv.isNative && isStockToken) {
    return <StockMobilePriceHeader />;
  }

  if (!tokenDetail) return <InformationPanelSkeleton />;

  const {
    name = '',
    symbol = '',
    price: currentPrice = '--',
    priceChange24hPercent = '--',
    marketCap,
    liquidity,
    priceConverted,
    holders = 0,
    communityRecognized,
    stock,
  } = tokenDetail;

  const formattedMarketCap = formatStatValueWithFormatter(
    marketCap,
    USD_CURRENCY_FORMATTER,
  );

  const formattedLiquidity = formatStatValueWithFormatter(
    liquidity,
    USD_CURRENCY_FORMATTER,
  );

  const formattedHolders = formatStatValueWithFormatter(
    holders,
    MARKET_CAP_FORMATTER,
  );

  const { color: priceChangeColor, display: priceChangeDisplay } =
    formatPriceChangeDisplay(priceChange24hPercent);

  const priceChangeValue = platformEnv.isNative
    ? resolveDisplayedPriceChange({
        price: currentPrice,
        priceChangePercent: priceChange24hPercent,
      })?.toFixed()
    : undefined;

  return (
    <XStack
      px="$5"
      py="$4"
      gap="$4"
      jc="space-between"
      ai="flex-start"
      width="100%"
    >
      <YStack>
        <YStack pointerEvents="none">
          {isPreviewTokenDetail ? (
            <BaseMarketTokenPrice
              size={getPriceSizeByValue(currentPrice)}
              price={currentPrice}
              tokenName={name}
              tokenSymbol={symbol}
            />
          ) : (
            <MarketTokenPrice
              size={getPriceSizeByValue(currentPrice)}
              price={currentPrice}
              tokenName={name}
              tokenSymbol={symbol}
              lastUpdated={tokenDetail.lastUpdated?.toString()}
            />
          )}
          {priceConverted ? (
            <NumberSizeableText
              size="$bodySm"
              color="$textSubdued"
              formatter="price"
              formatterOptions={{ currency: currencyInfo.symbol }}
            >
              {priceConverted}
            </NumberSizeableText>
          ) : null}
          <XStack pt="$1" ai="center" gap="$1.5">
            {priceChangeValue !== undefined ? (
              <NumberSizeableText
                testID="market-mobile-price-change-value"
                size="$bodyMdMedium"
                color={priceChangeColor}
                formatter="price"
                formatterOptions={{ currency: '$', showPlusMinusSigns: true }}
              >
                {priceChangeValue}
              </NumberSizeableText>
            ) : null}
            <SizableText
              size={platformEnv.isNative ? '$bodyMdMedium' : '$bodyLgMedium'}
              color={priceChangeColor}
            >
              {priceChangeValue !== undefined
                ? `(${priceChangeDisplay})`
                : priceChangeDisplay}
            </SizableText>
          </XStack>
        </YStack>
        <XStack
          ai="center"
          gap="$1"
          pt="$1"
          // Stock badges land with the detail response; hold their 16pt row.
          minHeight={isStockToken ? STOCK_TAG_ROW_MIN_HEIGHT : undefined}
        >
          <TokenTagsPopover
            communityRecognized={communityRecognized}
            stock={stock}
            showAllInTrigger
            hideCommunityInTrigger
            noTruncateSubtitle
          />
          <StockMarketStatusBadge stock={stock} />
        </XStack>
      </YStack>

      {platformEnv.isNative &&
      mobileDetailKind === 'trending' &&
      securityData ? (
        <XStack
          testID="market-detail-security-row"
          ai="center"
          gap="$1"
          bg="$bgStrong"
          borderRadius="$full"
          px="$2"
          py="$1.5"
        >
          <SizableText size="$bodySm" color="$textSubdued">
            {intl.formatMessage({ id: ETranslations.dexmarket_audit })}
          </SizableText>
          <TokenSecurityAlert />
        </XStack>
      ) : null}
      {platformEnv.isNative ? null : (
        <YStack gap="$1" width="$40" pt="$1">
          <HeaderStatRows
            isStockToken={Boolean(isStockToken)}
            isPreview={isPreviewTokenDetail}
            stock={stock}
            btcMetadata={btcMetadata}
            fallback={{
              marketCap: formattedMarketCap,
              liquidity: formattedLiquidity,
              holders: formattedHolders,
            }}
          />
          {securityData ? (
            <XStack
              testID="market-detail-security-row"
              gap="$1"
              ai="center"
              width="100%"
              jc="space-between"
            >
              <SizableText
                pointerEvents="none"
                size="$bodySm"
                color="$textSubdued"
              >
                {intl.formatMessage({ id: ETranslations.dexmarket_audit })}
              </SizableText>
              <TokenSecurityAlert />
            </XStack>
          ) : null}
        </YStack>
      )}
    </XStack>
  );
}
